function registerServiceWorker() {
  if (!("serviceWorker" in navigator)) return;
  if (!window.isSecureContext && location.hostname !== "localhost" && location.hostname !== "127.0.0.1") return;
  navigator.serviceWorker.register(`/service-worker.js?v=${encodeURIComponent(APP_VERSION)}`).catch(() => {});
}

function daysAgo(days, hours, minutes) {
  const date = new Date();
  date.setDate(date.getDate() - days);
  date.setHours(hours, minutes, 0, 0);
  return date.toISOString();
}

function createId() {
  if (globalThis.crypto && typeof globalThis.crypto.randomUUID === "function") {
    return globalThis.crypto.randomUUID();
  }
  return `exp-${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

function buildDemoAttachmentMetadata(label, kind) {
  const normalized = label.replace(/-/g, " ");
  const kindLabels = {
    image: "imagen",
    audio: "audio",
    video: "video",
    document: "documento",
  };
  return {
    manualTags: ["demo", kindLabels[kind] || "activo", normalized].filter(Boolean),
    manualNote: `Contexto demo para validar búsqueda, reportes y publicaciones con el activo ${normalized}.`,
    analysisText: `Lectura analítica demo: este ${kindLabels[kind] || "activo"} representa evidencia asociada a la experiencia y puede reutilizarse como memoria, reporte o publicación.`,
  };
}

function demoImageAttachment(label, color) {
  const svg = `
    <svg xmlns="http://www.w3.org/2000/svg" width="960" height="540" viewBox="0 0 960 540">
      <rect width="960" height="540" fill="${color}"/>
      <rect x="48" y="48" width="864" height="444" rx="24" fill="rgba(255,255,255,0.16)" stroke="rgba(255,255,255,0.45)" stroke-width="3"/>
      <text x="80" y="275" fill="white" font-family="Arial, sans-serif" font-size="58" font-weight="700">Demo ${label}</text>
      <text x="84" y="330" fill="rgba(255,255,255,0.82)" font-family="Arial, sans-serif" font-size="28">Experience Hub</text>
    </svg>
  `;
  return {
    id: createId(),
    name: `demo-${label}.svg`,
    type: "image/svg+xml",
    size: svg.length,
    dataUrl: `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`,
    ...buildDemoAttachmentMetadata(label, "image"),
    demo: true,
  };
}

