function t(path) {
  const parts = path.split(".");
  let value = i18n[state.language] || i18n.es;
  for (const part of parts) value = value?.[part];
  return value ?? path;
}

async function hydrateFromApi() {
  const startedAt = performance.now();
  try {
    const health = await apiRequest("/health", { skipAuth: true });
    state.apiOnline = true;
    state.persistence = health.persistence || "json-file";
    state.health = health;
    state.apiStatus = {
      ok: true,
      checkedAt: new Date().toISOString(),
      latencyMs: Math.round(performance.now() - startedAt),
      message: state.language === "en" ? "Local API responded correctly." : "La API local respondió correctamente.",
      service: health.service || "experience-hub-api",
      mode: health.persistence || "json-file",
    };

    if (state.persistence === "supabase" && !state.session?.access_token) {
      if (!state.experiences.length) {
        state.experiences = createDemoExperiences();
        saveExperiences();
      }
      renderAuthStatus();
      saveExperiences();
      return;
    }

    const [profile, experiences] = await Promise.all([apiRequest("/profile"), apiRequest("/experiences")]);
    state.profile = profile;
    saveLocalProfile(profile);
    if (profile.language && i18n[profile.language]) {
      state.language = profile.language;
      document.getElementById("languageSelect").value = state.language;
      applyLanguage();
    }
    if (Array.isArray(experiences) && experiences.length > 0) {
      state.experiences = normalizeExperiences(experiences);
      saveExperiences();
    } else if (state.persistence !== "supabase") {
      await Promise.all(state.experiences.map((experience) => saveExperienceToApi(experience)));
    } else {
      state.experiences = [];
      saveExperiences();
    }
    await syncOfflineQueue({ silent: true });
    await loadBackendRoutines();
  } catch (error) {
    state.apiOnline = false;
    state.persistence = "local";
    state.health = null;
    state.apiStatus = {
      ok: false,
      checkedAt: new Date().toISOString(),
      latencyMs: Math.round(performance.now() - startedAt),
      message: state.language === "en"
        ? `Local API did not respond. The app keeps working with local data. ${error.message || ""}`.trim()
        : `La API local no respondió. La app sigue funcionando con datos locales. ${error.message || ""}`.trim(),
      service: "",
      mode: "local",
    };
  }
}

