async function saveExperienceToApi(experience) {
  if (!state.apiOnline) {
    queueOfflineMutation("upsert", experience, "api_unavailable");
    return { remote: false, queued: true, reason: "api_unavailable" };
  }
  try {
    await apiRequest(`/experiences/${encodeURIComponent(experience.id)}`, {
      method: "PUT",
      body: JSON.stringify({ ...experience, locale: state.language }),
    });
    return { remote: true, queued: false };
  } catch {
    state.apiOnline = false;
    queueOfflineMutation("upsert", experience, "api_error");
    return { remote: false, queued: true, reason: "api_error" };
  }
}

async function deleteExperienceFromApi(id) {
  if (!state.apiOnline) {
    queueOfflineMutation("delete", { id }, "api_unavailable");
    return;
  }
  try {
    await apiRequest(`/experiences/${encodeURIComponent(id)}`, { method: "DELETE" });
  } catch {
    state.apiOnline = false;
    queueOfflineMutation("delete", { id }, "api_error");
  }
}

function queueOfflineMutation(type, payload, reason = "api_error") {
  const id = type === "delete" ? payload.id : payload.id;
  if (payload?.isDemo && !state.session?.access_token && (state.config?.persistence === "supabase" || state.persistence === "supabase")) {
    return;
  }
  state.offlineQueue = state.offlineQueue.filter((item) => !(item.entityId === id && item.type === type));
  if (type === "delete") {
    state.offlineQueue = state.offlineQueue.filter((item) => item.entityId !== id);
  }
  state.offlineQueue.push({
    id: createId(),
    type,
    entityId: id,
    payload,
    reason,
    attempts: 0,
    createdAt: new Date().toISOString(),
  });
  saveOfflineQueue();
}

async function syncOfflineQueue(options = {}) {
  if (!state.offlineQueue.length) {
    if (!options.silent) document.getElementById("embeddingStatus").textContent = "No hay cambios sin conexión pendientes.";
    renderAdmin();
    return;
  }
  if (!state.session?.access_token && state.config?.persistence === "supabase") {
    if (!options.silent) document.getElementById("embeddingStatus").textContent = "Inicia sesión para sincronizar sin conexión.";
    state.offlineQueue = state.offlineQueue.map((item) => ({ ...item, reason: item.reason || "auth_required" }));
    saveOfflineQueue();
    renderOfflineQueuePanel();
    return;
  }
  if (!options.silent) document.getElementById("embeddingStatus").textContent = "Sincronizando cambios sin conexión...";
  try {
    await apiRequest("/health", { skipAuth: true });
    state.apiOnline = true;
  } catch {
    state.apiOnline = false;
    if (!options.silent) document.getElementById("embeddingStatus").textContent = "API no disponible para sincronizar.";
    renderAdmin();
    return;
  }

  const remaining = [];
  for (const mutation of state.offlineQueue) {
    const synced = await syncOfflineMutation(mutation);
    if (!synced) {
      remaining.push({ ...mutation, reason: "api_error", attempts: mutation.attempts + 1 });
    }
  }
  state.offlineQueue = remaining;
  saveOfflineQueue();
  renderOfflineQueuePanel();
  if (!options.silent) {
    document.getElementById("embeddingStatus").textContent = remaining.length
      ? `${remaining.length} cambios siguen pendientes.`
      : "Cambios sin conexión sincronizados.";
  }
  renderAdmin();
}

async function syncOfflineMutation(mutation) {
  try {
    if (mutation.type === "delete") {
      await apiRequest(`/experiences/${encodeURIComponent(mutation.entityId)}`, { method: "DELETE" });
    } else {
      await apiRequest(`/experiences/${encodeURIComponent(mutation.entityId)}`, {
        method: "PUT",
        body: JSON.stringify({ ...mutation.payload, locale: state.language }),
      });
    }
    return true;
  } catch {
    return false;
  }
}

function clearLocalData() {
  const message =
    "Esto vaciará las experiencias visibles, la agenda local, las publicaciones, los metadatos de activos, el perfil local, el Diario, las rutinas, los adjuntos locales y la cola sin conexión de este navegador. No borra datos remotos ya guardados en Supabase ni cierra tu sesión. Haz un respaldo de datos antes si quieres conservar una copia. ¿Continuar?";
  if (!confirm(message)) return;
  state.experiences = [];
  state.agendaEvents = [];
  state.agendaBlockedDates = [];
  state.publicationDrafts = [];
  state.assetMetadata = {};
  state.assetMetadataImportSummary = null;
  state.currentPublicationDraft = null;
  state.pendingAttachments = [];
  state.offlineQueue = [];
  state.profile = null;
  state.contextImpact = null;
  state.dailyBriefing = null;
  state.selectedDailyArticle = null;
  state.routineSettings = {};
  state.manualReview = {};
  recordBackupAudit("clear", buildLocalBackupPayload());
  saveExperiences();
  saveAgendaEvents();
  saveAgendaBlockedDates();
  savePublicationDrafts();
  saveAssetMetadata();
  saveAssetMetadataImportSummary();
  saveLocalProfile(null);
  saveDailyBriefing();
  saveRoutineSettings();
  saveManualReview();
  saveOfflineQueue();
  renderOfflineQueuePanel();
  renderAll();
  showView("capture");
  document.getElementById("embeddingStatus").textContent = "Datos locales vaciados. Puedes iniciar tu carga real; la sesión y el idioma se conservaron.";
}

