function renderCoreMvpReturnBanner(activeView = document.querySelector(".active-view")?.id?.replace("View", "") || "") {
  const banner = document.getElementById("mvpReturnBanner");
  if (!banner) return;
  if (!state.coreMvpReturn || activeView === "admin") {
    banner.innerHTML = "";
    banner.hidden = true;
    return;
  }
  const labels = state.language === "en"
    ? {
        title: "MVP closure action in progress",
        detail: "Complete this step, then return to Admin to save evidence and continue the real test.",
        evidence: "Evidence observed in this module",
        evidencePlaceholder: "What did you test and what was the result?",
        saveAndBack: "Save evidence and return",
        back: "Return to MVP closure",
        dismiss: "Dismiss",
      }
    : {
        title: "Acción de cierre del MVP en curso",
        detail: "Completa este paso y vuelve a Administración para guardar evidencia y continuar la prueba real.",
        evidence: "Evidencia observada en este módulo",
        evidencePlaceholder: "¿Qué probaste y cuál fue el resultado?",
        saveAndBack: "Guardar evidencia y volver",
        back: "Volver al cierre MVP",
        dismiss: "Ocultar",
      };
  const stepKey = state.coreMvpReturn.stepKey || "";
  const savedStep = stepKey ? state.coreMvpManualTest?.[stepKey] || {} : {};
  banner.hidden = false;
  banner.innerHTML = `
    <div>
      <strong>${escapeHtml(labels.title)}</strong>
      <p>${escapeHtml(labels.detail)}</p>
      ${
        stepKey
          ? `<label class="mvp-return-evidence">
              <span>${escapeHtml(labels.evidence)}</span>
              <textarea data-mvp-return-note rows="2" placeholder="${escapeHtml(labels.evidencePlaceholder)}">${escapeHtml(savedStep.note || "")}</textarea>
            </label>`
          : ""
      }
    </div>
    <div>
      ${stepKey ? `<button class="primary-button" type="button" data-mvp-return-action="save-back">${escapeHtml(labels.saveAndBack)}</button>` : ""}
      <button class="primary-button" type="button" data-mvp-return-action="back">${escapeHtml(labels.back)}</button>
      <button class="ghost-button" type="button" data-mvp-return-action="dismiss">${escapeHtml(labels.dismiss)}</button>
    </div>
  `;
}

function handleCoreMvpReturnBannerClick(event) {
  const action = event.target.closest("[data-mvp-return-action]")?.dataset.mvpReturnAction;
  if (!action) return;
  if (action === "dismiss") {
    state.coreMvpReturn = null;
    renderCoreMvpReturnBanner();
    return;
  }
  if (action === "save-back") {
    const stepKey = state.coreMvpReturn?.stepKey || "";
    const note = String(document.querySelector("[data-mvp-return-note]")?.value || "").trim();
    if (!stepKey || !note) {
      notify(state.language === "en" ? "Add evidence before returning to closure." : "Agrega evidencia antes de volver al cierre.", "warn");
      return;
    }
    const now = new Date().toISOString();
    const previousStep = state.coreMvpManualTest?.[stepKey] || {};
    state.coreMvpManualTest[stepKey] = {
      ...previousStep,
      done: true,
      updatedAt: now,
      note,
      noteUpdatedAt: now,
    };
    saveCoreMvpManualTest();
    notify(state.language === "en" ? "Evidence saved and step completed." : "Evidencia guardada y paso completado.", "success");
  }
  showView("admin");
  requestAnimationFrame(() => {
    focusAppElement("coreMvpGatePanel");
    state.coreMvpReturn = null;
    renderCoreMvpReturnBanner("admin");
  });
}

