function setupForm() {
  const form = document.getElementById("experienceForm");
  document.getElementById("timestampInput").value = toDatetimeLocal(new Date().toISOString());

  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    try {
      const experience = await readForm();
      const existingIndex = state.experiences.findIndex((item) => item.id === experience.id);

      if (existingIndex >= 0) {
        state.experiences[existingIndex] = experience;
      } else {
        state.experiences.unshift(experience);
      }

      const localSaved = saveExperiences();
      const apiResult = await saveExperienceToApi(experience);
      const agendaSynced = document.getElementById("syncAgendaInput")?.checked ? syncExperienceToAgenda(experience) : false;
      state.lastSavedExperienceId = experience.id;
      state.captureSaveStatus = buildCaptureSaveStatus(experience, { ...apiResult, localSaved }, existingIndex >= 0);
      if (agendaSynced) {
        state.captureSaveStatus.detail += state.language === "en" ? " Agenda was updated." : " Agenda/Calendario fue actualizado.";
      }
      resetLibraryFilters({ syncInputs: false });
      notify(state.captureSaveStatus.detail, apiResult?.queued || !localSaved ? "warn" : "success");
      clearForm();
      renderAll();
      showView("capture");
    } catch (error) {
      const detail = state.language === "en"
        ? "The experience could not be saved. Review required fields and try again."
        : "No se pudo guardar la experiencia. Revisa los campos obligatorios e inténtalo de nuevo.";
      state.captureSaveStatus = {
        type: "warn",
        title: state.language === "en" ? "Save failed" : "Guardado no completado",
        detail,
        experienceId: "",
        experienceTitle: "",
        savedAt: new Date().toISOString(),
      };
      renderCaptureSaveStatus();
      notify(detail, "warn");
      console.warn("Experience save failed", error);
    }
  });

  document.getElementById("clearFormButton").addEventListener("click", clearForm);
  document.getElementById("mediaInput").addEventListener("change", handleMediaSelection);
  form.addEventListener("input", renderCaptureWritingCoach);
  form.addEventListener("change", renderCaptureWritingCoach);
  document.getElementById("captureSaveStatus")?.addEventListener("click", handleCaptureSaveStatusClick);
}

