function syncReportFilterInputs() {
  const scope = document.getElementById("reportScopeFilter");
  const period = document.getElementById("reportPeriodFilter");
  const category = document.getElementById("reportCategoryFilter");
  const pilotParticipant = document.getElementById("reportPilotParticipantFilter");
  const people = document.getElementById("reportPeopleFilter");
  const objective = document.getElementById("reportObjectiveFilter");
  const experience = document.getElementById("reportExperienceFilter");
  if (scope) scope.value = state.reportFilters.scope || "all";
  if (period) period.value = state.reportFilters.period || "all";
  if (category) category.value = state.reportFilters.category || "all";
  if (pilotParticipant) pilotParticipant.value = state.reportFilters.pilotParticipantId || "all";
  if (people) people.value = state.reportFilters.people || "";
  if (objective) objective.value = state.reportFilters.objective || "";
  if (experience) experience.value = state.reportFilters.experienceId || "";
}

function generateReportFromScope() {
  renderReport();
  const count = getReportExperiences().length;
  const scope = state.reportFilters.scope || "all";
  const scopeText = getReportScopeLabel(scope);
  setReportFlowStatus(
    state.language === "en"
      ? `Report generated for ${count} experience(s). Scope: ${scopeText}. Continue with the acceptance pack.`
      : `Reporte generado para ${count} experiencia(s). Alcance: ${scopeText}. Lee la síntesis principal y luego usa el paquete de aceptación.`,
  );
  document.getElementById("reportSummary")?.scrollIntoView({ behavior: "smooth", block: "nearest" });
  notify(state.language === "en" ? "Report generated." : "Reporte generado.", "success");
}

function resetReportScope() {
  state.reportFilters = {
    scope: "all",
    period: "all",
    experienceId: "",
    category: "all",
    pilotParticipantId: "all",
    people: "",
    objective: "",
  };
  syncReportFilterInputs();
  renderReport();
  setReportFlowStatus(state.language === "en" ? "Scope cleared. The report now uses all saved experiences." : "Alcance limpiado. El reporte ahora usa todas las experiencias guardadas.");
}

function scrollToReportAcceptance() {
  renderReportAcceptancePanel();
  document.getElementById("reportAcceptancePanel")?.scrollIntoView({ behavior: "smooth", block: "start" });
  setReportFlowStatus(state.language === "en" ? "Review the acceptance pack and run the needed export buttons." : "Revisa el paquete de aceptación y ejecuta los botones de exportación necesarios.");
}

function setReportFlowStatus(message) {
  const status = document.getElementById("reportFlowStatus");
  if (status) status.textContent = message;
}

function handleReportScopeAction(event) {
  const target = event.target.closest("button");
  if (!target) return;
  if (target.id === "generateReportButton") generateReportFromScope();
  if (target.id === "resetReportScopeButton") resetReportScope();
  if (target.id === "jumpReportAcceptanceButton") scrollToReportAcceptance();
}

function getReportScopeLabel(scope = state.reportFilters.scope) {
  const labels =
    state.language === "en"
      ? {
          all: "all experiences",
          period: "quick range",
          filters: "category, person, or objective filters",
          single: "one specific experience",
        }
      : {
          all: "todas las experiencias",
          period: "rango rápido",
          filters: "categoría, persona u objetivo",
          single: "una experiencia específica",
        };
  return labels[scope] || labels.all;
}

