function handleOfflineQueueAction(event) {
  const button = event.target.closest("[data-offline-action]");
  if (!button) return;
  const action = button.dataset.offlineAction;
  if (action === "retry") {
    syncOfflineQueue();
    return;
  }
  if (action === "auth") {
    state.pendingAuthReturn = "admin";
    showAuthView();
    requestAnimationFrame(() => {
      const message = document.getElementById("authMessage");
      if (message) message.textContent = t("labels.offlineQueueNextLogin");
      document.getElementById("authEmailInput")?.focus();
    });
    return;
  }
  if (action === "review") {
    reviewOfflineMutation(button.dataset.offlineId);
    return;
  }
  if (action === "retry-one") {
    retryOfflineMutation(button.dataset.offlineId);
    return;
  }
  if (action === "keep-local") {
    keepLocalOfflineMutation(button.dataset.offlineId);
    return;
  }
  if (action === "discard") {
    discardOfflineMutation(button.dataset.offlineId);
    return;
  }
  if (action === "clear-demo") {
    clearDemoOfflineMutations();
    return;
  }
  if (action === "clear") {
    if (!state.offlineQueue.length) return;
    if (!confirm(t("labels.offlineQueueClearConfirm"))) return;
    state.offlineQueue = [];
    saveOfflineQueue();
    document.getElementById("embeddingStatus").textContent = t("labels.offlineQueueCleared");
    renderOfflineQueuePanel();
    renderAdmin();
  }
}

function clearDemoOfflineMutations() {
  const demoQueue = state.offlineQueue.filter(isDemoOfflineMutation);
  if (!demoQueue.length) return;
  if (!confirm(`Se descartarán ${demoQueue.length} cambios sin conexión de ejemplo. No se borran datos reales. ¿Continuar?`)) return;
  state.offlineQueue = state.offlineQueue.filter((item) => !isDemoOfflineMutation(item));
  saveOfflineQueue();
  document.getElementById("embeddingStatus").textContent = `${demoQueue.length} cambios de ejemplo descartados de la cola sin conexión.`;
  renderOfflineQueuePanel();
  renderAdmin();
}

function handleDemoDataAction(event) {
  const button = event.target.closest("[data-demo-action]");
  if (!button) return;
  const action = button.dataset.demoAction;
  if (action === "load") {
    loadDemoData();
    return;
  }
  if (action === "clear") {
    clearDemoData();
    return;
  }
  if (action === "auth") {
    state.pendingAuthReturn = "admin";
    showAuthView();
    requestAnimationFrame(() => {
      const message = document.getElementById("authMessage");
      if (message) message.textContent = t("labels.demoDataLocal");
      document.getElementById("authEmailInput")?.focus();
    });
    return;
  }
  if (action === "sync") {
    syncDemoDataToApi();
  }
}

async function syncDemoDataToApi() {
  const demoItems = state.experiences.filter((item) => item.isDemo);
  const status = document.getElementById("embeddingStatus");
  if (!demoItems.length) {
    status.textContent = t("labels.demoDataEmpty");
    renderDemoDataPanel();
    return;
  }
  if (!state.session?.access_token && (state.config?.persistence === "supabase" || state.persistence === "supabase")) {
    state.pendingAuthReturn = "admin";
    showAuthView();
    return;
  }
  status.textContent = "Sincronizando datos de ejemplo...";
  try {
    await Promise.all(demoItems.map((experience) => saveExperienceToApi(experience)));
    status.textContent = t("labels.demoDataSynced");
  } catch {
    status.textContent = "No se pudieron sincronizar los datos de ejemplo. Revisa Verificar Supabase.";
  }
  renderDemoDataPanel();
  renderAdmin();
}

async function retryOfflineMutation(id) {
  const mutation = state.offlineQueue.find((item) => item.id === id);
  if (!mutation) return;
  if (!state.session?.access_token && (state.config?.persistence === "supabase" || state.persistence === "supabase")) {
    state.pendingAuthReturn = "admin";
    showAuthView();
    return;
  }
  document.getElementById("embeddingStatus").textContent = t("labels.offlineQueueRetry");
  const synced = await syncOfflineMutation(mutation);
  if (synced) {
    state.offlineQueue = state.offlineQueue.filter((item) => item.id !== id);
    document.getElementById("embeddingStatus").textContent = t("labels.offlineQueueRetried");
  } else {
    state.offlineQueue = state.offlineQueue.map((item) =>
      item.id === id ? { ...item, reason: "api_error", attempts: Number(item.attempts || 0) + 1 } : item,
    );
    document.getElementById("embeddingStatus").textContent = t("labels.offlineQueueRetryFailed");
  }
  saveOfflineQueue();
  renderOfflineQueuePanel();
  renderAdmin();
}

function reviewOfflineMutation(id) {
  const mutation = state.offlineQueue.find((item) => item.id === id);
  if (!mutation) return;
  if (mutation.type === "upsert" && mutation.payload) {
    loadExperienceIntoForm(mutation.payload);
    document.getElementById("embeddingStatus").textContent = t("labels.offlineQueueOpened");
    return;
  }
  const experience = state.experiences.find((item) => item.id === mutation.entityId);
  if (experience) {
    showExperienceInTimeline(experience.id);
  }
}

function discardOfflineMutation(id) {
  if (!id) return;
  if (!confirm(t("labels.offlineQueueDiscardConfirm"))) return;
  state.offlineQueue = state.offlineQueue.filter((item) => item.id !== id);
  saveOfflineQueue();
  document.getElementById("embeddingStatus").textContent = t("labels.offlineQueueDiscarded");
  renderOfflineQueuePanel();
  renderAdmin();
}

function keepLocalOfflineMutation(id) {
  if (!id) return;
  state.offlineQueue = state.offlineQueue.map((item) =>
    item.id === id
      ? {
          ...item,
          conflictPolicy: item.type === "delete" ? "delete_wins" : "local_wins",
          reason: "api_error",
          updatedAt: new Date().toISOString(),
        }
      : item,
  );
  saveOfflineQueue();
  document.getElementById("embeddingStatus").textContent = t("labels.offlineQueueKeptLocal");
  renderOfflineQueuePanel();
  renderAdmin();
}

function handleDiagnosticAction(event) {
  const button = event.target.closest("[data-diagnostic-action]");
  if (!button) return;
  const action = button.dataset.diagnosticAction;
  if (action === "openAuth") {
    state.pendingAuthReturn = button.dataset.authReturn || null;
    showAuthView();
    requestAnimationFrame(() => {
      const message = document.getElementById("authMessage");
      if (message && state.pendingAuthReturn === "diagnostics") message.textContent = t("labels.authReturnDiagnostics");
      if (message && state.pendingAuthReturn === "selfTest") message.textContent = t("labels.authReturnSelfTest");
      document.getElementById("authEmailInput")?.focus();
    });
  }
  if (action === "openAdmin") {
    showView("admin");
  }
}

function handleParallelBacklogClick(event) {
  const button = event.target.closest("[data-backlog-view]");
  if (!button) return;
  const view = button.dataset.backlogView;
  if (button.dataset.backlogReturn === "coreMvpGatePanel") {
    state.coreMvpReturn = {
      fromView: view || "",
      focus: "coreMvpGatePanel",
      stepKey: button.dataset.mvpReturnStep || "",
      label: button.textContent.trim(),
      at: new Date().toISOString(),
    };
  }
  if (view) showView(view);
  const run = button.dataset.backlogRun;
  if (run === "syncOffline") syncOfflineQueue();
  if (run === "refreshOps") refreshOps();
  if (run === "backfillEmbeddings") backfillEmbeddings();
  if (run === "showPendingAssetText") showPendingAssetText();
  if (run === "openAuthDiagnostics") {
    state.pendingAuthReturn = "quickQaDiagnostics";
    showAuthView();
    requestAnimationFrame(() => {
      const message = document.getElementById("authMessage");
      if (message) message.textContent = t("labels.authReturnQuickQa");
    });
  }
  if (run === "runSupabaseDiagnostics") runSupabaseDiagnostics();
  if (run === "runSupabaseSelfTest") runSupabaseSelfTest();
  const focusId = button.dataset.backlogFocus;
  if (focusId) requestAnimationFrame(() => focusAppElement(focusId));
  renderCoreMvpReturnBanner(view);
}

function focusAppElement(id) {
  const element = document.getElementById(id);
  if (!element) return;
  document.querySelectorAll(".focus-target").forEach((item) => item.classList.remove("focus-target"));
  if (!element.hasAttribute("tabindex")) element.setAttribute("tabindex", "-1");
  element.scrollIntoView({ behavior: "smooth", block: "start" });
  element.focus({ preventScroll: true });
  element.classList.add("focus-target");
  window.setTimeout(() => element.classList.remove("focus-target"), 2600);
}

function showPendingAssetText() {
  state.assetFilters.analysis = "without";
  state.assetFilters.processing = "pending";
  const select = document.getElementById("assetAnalysisFilter");
  if (select) select.value = "without";
  const processingSelect = document.getElementById("assetProcessingFilter");
  if (processingSelect) processingSelect.value = "pending";
  renderAssetLibrary();
  requestAnimationFrame(() => focusAppElement("assetProcessingActionPlan"));
}

function suggestAnalysisForFilteredAssets() {
  const assets = filterMultimodalAssets().filter((asset) => !String(asset.analysisText || "").trim());
  if (!assets.length) {
    const intro = document.getElementById("assetLibraryIntro");
    if (intro) intro.textContent = t("labels.assetBulkSuggestedAnalysisEmpty");
    notify(t("labels.assetBulkSuggestedAnalysisEmpty"), "warn");
    return;
  }
  assets.forEach((asset) => {
    const existing = state.assetMetadata[asset.assetKey] || {};
    const tags = Array.isArray(existing.tags) ? existing.tags : Array.isArray(asset.manualTags) ? asset.manualTags : [];
    const note = Object.hasOwn(existing, "note") ? existing.note : asset.manualNote || "";
    const analysisText = buildSuggestedAssetAnalysisText(asset, { tags, note });
    state.assetMetadata[asset.assetKey] = { tags, note, analysisText, updatedAt: new Date().toISOString(), suggested: true };
  });
  saveAssetMetadata();
  renderAssetLibrary();
  const message = t("labels.assetBulkSuggestedAnalysisSaved").replace("{count}", String(assets.length));
  const intro = document.getElementById("assetLibraryIntro");
  if (intro) intro.textContent = message;
  notify(message);
}

