function clearSingleAssetFilter(key) {
  const defaults = {
    query: "",
    type: "all",
    category: "all",
    readiness: "all",
    processing: "all",
    provenance: "all",
    analysis: "all",
    sort: "newest",
    dateFrom: "",
    dateTo: "",
  };
  if (!Object.hasOwn(defaults, key)) return;
  state.assetFilters[key] = defaults[key];
  const inputMap = {
    query: "assetSearchInput",
    type: "assetTypeFilter",
    category: "assetCategoryFilter",
    readiness: "assetReadinessFilter",
    processing: "assetProcessingFilter",
    provenance: "assetProvenanceFilter",
    analysis: "assetAnalysisFilter",
    sort: "assetSortFilter",
    dateFrom: "assetDateFromFilter",
    dateTo: "assetDateToFilter",
  };
  const input = document.getElementById(inputMap[key]);
  if (input) input.value = defaults[key];
  renderAssetLibrary();
  requestAnimationFrame(() => document.getElementById(inputMap[key])?.focus());
}

function handleCaptureCoachClick(event) {
  const applyButton = event.target.closest("[data-writing-apply]");
  if (applyButton) {
    applyCaptureWritingSuggestion(Number(applyButton.dataset.writingApply));
    return;
  }
  const copilotButton = event.target.closest("[data-writing-copilot]");
  if (copilotButton) {
    openCaptureWritingCopilot(Number(copilotButton.dataset.writingCopilot));
    return;
  }
  const button = event.target.closest("[data-coach-field]");
  if (!button) return;
  const field = document.getElementById(button.dataset.coachField);
  field?.focus();
}

async function loadDemoData() {
  if (state.experiences.some((item) => !item.isDemo)) {
    const message =
      "Esto agregará datos de ejemplo sin borrar tus experiencias reales. Podrás quitarlos luego con Eliminar ejemplo. ¿Continuar?";
    if (!confirm(message)) return;
  }
  const existingDemo = state.experiences.filter((item) => item.isDemo);
  const existingReal = state.experiences.filter((item) => !item.isDemo);
  const nextDemo = createDemoExperiences();
  const nextDemoAgenda = createDemoAgendaEvents();
  state.experiences = [...nextDemo, ...existingReal];
  state.agendaEvents = [...nextDemoAgenda, ...state.agendaEvents.filter((item) => !item.isDemo)];
  saveExperiences();
  saveAgendaEvents();
  if (state.apiOnline && state.session?.access_token) {
    try {
      await Promise.all(existingDemo.map((experience) => deleteExperienceFromApi(experience.id)));
      await Promise.all(nextDemo.map((experience) => saveExperienceToApi(experience)));
    } catch {
      state.apiOnline = false;
    }
  }
  renderAll();
  showView("assetLibrary");
  const agendaDetail = t("labels.demoAgendaLoaded").replace("{count}", String(nextDemoAgenda.length));
  const baseMessage = `${nextDemo.length} experiencias de ejemplo multimodales cargadas. ${agendaDetail}`;
  document.getElementById("embeddingStatus").textContent = state.session?.access_token
    ? baseMessage
    : `${baseMessage} Entra para sincronizarlas con Supabase.`;
}

async function clearDemoData() {
  const demoItems = state.experiences.filter((item) => item.isDemo);
  const demoAgendaItems = state.agendaEvents.filter((item) => item.isDemo);
  if (!demoItems.length && !demoAgendaItems.length) {
    document.getElementById("embeddingStatus").textContent = "No hay datos de ejemplo para eliminar.";
    return;
  }
  if (!confirm(`Se eliminarán ${demoItems.length} experiencias y ${demoAgendaItems.length} eventos de Agenda de ejemplo. Tus datos reales se conservan. ¿Continuar?`)) return;
  state.experiences = state.experiences.filter((item) => !item.isDemo);
  state.agendaEvents = state.agendaEvents.filter((item) => !item.isDemo);
  saveExperiences();
  saveAgendaEvents();
  if (state.apiOnline && state.session?.access_token) {
    await Promise.all(demoItems.map((experience) => deleteExperienceFromApi(experience.id))).catch(() => {
      state.apiOnline = false;
    });
  }
  renderAll();
  document.getElementById("embeddingStatus").textContent = "Datos de ejemplo eliminados.";
}

