function renderPublicationFinalMediaItem(item) {
  const caption = renderPublicationMediaCaption(item);
  if (!item.url && !item.dataUrl) {
    return `<figure class="publication-file media-sync-missing">${renderPublicationMediaSyncNotice(item)}${caption}</figure>`;
  }
  const source = escapeHtml(item.url || item.dataUrl);
  if (item.type.startsWith("image/")) {
    return `<figure><img src="${source}" alt="${escapeHtml(item.name)}" loading="lazy" />${caption}</figure>`;
  }
  if (item.type.startsWith("video/")) {
    return `<figure><video src="${source}" controls muted playsinline preload="metadata"></video>${caption}</figure>`;
  }
  if (item.type.startsWith("audio/")) {
    return `<figure class="publication-audio"><audio src="${source}" controls preload="metadata"></audio>${caption}</figure>`;
  }
  return `<figure class="publication-file">${caption}</figure>`;
}

function renderPublicationReadiness(draft) {
  const readiness = buildPublicationReadiness(draft);
  const statusLabel = readiness.score >= 75 ? t("labels.publicationReady") : t("labels.publicationNeedsReview");
  return `
    <section class="publication-readiness">
      <div class="publication-readiness-heading">
        <div>
          <h3>${escapeHtml(t("labels.publicationReadiness"))}</h3>
          <span>${escapeHtml(statusLabel)}</span>
        </div>
        <strong>${readiness.score}%</strong>
      </div>
      <div class="publication-check-grid">
        ${readiness.checks
          .map(
            (check) => `
              <article>
                <span>${escapeHtml(check.label)}</span>
                <strong>${check.score}%</strong>
                <p>${escapeHtml(check.detail)}</p>
              </article>
            `,
          )
          .join("")}
      </div>
      <div class="publication-suggestions">
        <strong>${escapeHtml(t("labels.publicationSuggestions"))}</strong>
        <ul>
          ${readiness.suggestions.map((suggestion) => `<li>${escapeHtml(suggestion)}</li>`).join("")}
        </ul>
      </div>
    </section>
  `;
}

function renderPublicationClosureChecklist(draft) {
  const readiness = buildPublicationReadiness(draft);
  const words = countWords(`${draft.summary} ${draft.body}`);
  const limit = getPublicationWordLimit(draft.channel);
  const totalMedia = (draft.media || []).length;
  const includedMedia = getApprovedPublicationMedia(draft).length;
  const textReady = words >= 45 && words <= limit;
  const mediaReady = !channelBenefitsFromMedia(draft.channel) || includedMedia > 0;
  const items = [
    {
      label: t("labels.publicationClosureApproval"),
      ready: draft.approvalStatus === "approved",
      detail:
        draft.approvalStatus === "approved"
          ? t("labels.publicationClosureApprovalReady")
          : t("labels.publicationClosureApprovalReview"),
    },
    {
      label: t("labels.publicationClosureText"),
      ready: textReady,
      detail: textReady
        ? `${t("labels.publicationClosureTextReady")} ${words}/${limit}.`
        : `${t("labels.publicationClosureTextReview")} ${words}/${limit}.`,
    },
    {
      label: t("labels.publicationClosurePrivacy"),
      ready: Boolean(draft.privacy),
      detail: draft.privacy ? t("labels.publicationClosurePrivacyReady") : t("labels.publicationClosurePrivacyReview"),
    },
    {
      label: t("labels.publicationClosureMedia"),
      ready: mediaReady,
      detail: mediaReady
        ? `${t("labels.publicationClosureMediaReady")} ${includedMedia}/${totalMedia}.`
        : `${t("labels.publicationClosureMediaReview")} ${includedMedia}/${totalMedia}.`,
    },
    {
      label: t("labels.publicationClosureChannel"),
      ready: readiness.score >= 75,
      detail:
        readiness.score >= 75
          ? `${t("labels.publicationClosureChannelReady")} ${readiness.score}%.`
          : `${t("labels.publicationClosureChannelReview")} ${readiness.score}%.`,
    },
  ];
  const readyCount = items.filter((item) => item.ready).length;
  const progress = t("labels.publicationClosureProgress").replace("{ready}", String(readyCount)).replace("{total}", String(items.length));
  return `
    <section class="publication-closure-checklist">
      <div class="publication-section-heading">
        <div>
          <h3>${escapeHtml(t("labels.publicationClosureTitle"))}</h3>
          <p class="card-meta">${escapeHtml(t("labels.publicationClosureHelp"))}</p>
        </div>
        <span>${escapeHtml(progress)}</span>
      </div>
      <div class="publication-closure-grid">
        ${items
          .map(
            (item) => `
              <article class="publication-closure-item ${item.ready ? "is-ready" : "is-review"}">
                <span>${escapeHtml(item.ready ? t("labels.publicationClosureReady") : t("labels.publicationClosureReview"))}</span>
                <strong>${escapeHtml(item.label)}</strong>
                <p>${escapeHtml(item.detail)}</p>
              </article>
            `,
          )
          .join("")}
      </div>
    </section>
  `;
}

function buildPublicationReadiness(draft) {
  const words = countWords(`${draft.summary} ${draft.body}`);
  const includedMedia = getApprovedPublicationMedia(draft).length;
  const totalMedia = (draft.media || []).length;
  const readability = scorePublicationReadability(words, draft.channel);
  const privacyScore = draft.privacy ? 92 : 48;
  const mediaScore = totalMedia ? Math.round((includedMedia / totalMedia) * 100) : channelBenefitsFromMedia(draft.channel) ? 45 : 80;
  const channelScore = scorePublicationChannelFit(draft, words, includedMedia);
  const score = Math.round((readability.score + privacyScore + mediaScore + channelScore.score) / 4);
  const suggestions = buildPublicationSuggestions({ draft, words, includedMedia, totalMedia, readability, privacyScore, mediaScore, channelScore });
  return {
    score,
    checks: [
      { label: t("labels.publicationReadability"), score: readability.score, detail: readability.detail },
      {
        label: t("labels.publicationPrivacy"),
        score: privacyScore,
        detail: draft.privacy
          ? state.language === "en"
            ? "Automatic cleanup is active."
            : "La limpieza automática está activa."
          : state.language === "en"
            ? "Automatic cleanup is disabled."
            : "La limpieza automática está desactivada.",
      },
      {
        label: t("labels.publicationMediaUse"),
        score: mediaScore,
        detail: totalMedia
          ? state.language === "en"
            ? `${includedMedia}/${totalMedia} media assets selected.`
            : `${includedMedia}/${totalMedia} activos multimedia seleccionados.`
          : state.language === "en"
            ? "No linked media is available."
            : "No hay multimedia vinculada disponible.",
      },
      { label: t("labels.publicationChannelFit"), score: channelScore.score, detail: channelScore.detail },
    ],
    suggestions,
  };
}

function countWords(value) {
  return String(value || "").trim().split(/\s+/).filter(Boolean).length;
}

function scorePublicationReadability(words, channel) {
  const limit = getPublicationWordLimit(channel);
  if (words <= limit) {
    return {
      score: words < 45 ? 68 : 92,
      detail: state.language === "en" ? `${words} words; length is manageable.` : `${words} palabras; la extensión es manejable.`,
    };
  }
  const overRatio = Math.min(1, (words - limit) / Math.max(1, limit));
  return {
    score: Math.max(45, Math.round(88 - overRatio * 45)),
    detail:
      state.language === "en"
        ? `${words} words; recommended limit for ${channel}: ${limit}.`
        : `${words} palabras; límite recomendado para ${channel}: ${limit}.`,
  };
}

function getPublicationWordLimit(channel) {
  const limits = {
    WhatsApp: 180,
    Instagram: 160,
    Facebook: 220,
    Email: 420,
    "PDF/HTML": 650,
  };
  return limits[channel] || 280;
}

function channelBenefitsFromMedia(channel) {
  return ["Instagram", "Facebook", "PDF/HTML"].includes(channel);
}

function scorePublicationChannelFit(draft, words, includedMedia) {
  const limit = getPublicationWordLimit(draft.channel);
  let score = words <= limit ? 88 : 60;
  if (channelBenefitsFromMedia(draft.channel)) score += includedMedia ? 8 : -18;
  if (draft.channel === "WhatsApp" && words <= 160) score += 6;
  if (draft.channel === "Email" && words >= 90) score += 5;
  score = Math.max(35, Math.min(100, score));
  return {
    score,
    detail:
      state.language === "en"
        ? `${displayPublicationType(draft.type)} adapted for ${draft.channel}.`
        : `${displayPublicationType(draft.type)} adaptada para ${draft.channel}.`,
  };
}

function buildPublicationSuggestions({ draft, words, includedMedia, totalMedia, readability, privacyScore, mediaScore, channelScore }) {
  const suggestions = [];
  const limit = getPublicationWordLimit(draft.channel);
  if (words > limit) {
    suggestions.push(
      state.language === "en"
        ? "Shorten the draft or move detail into a longer report before publishing."
        : "Reduce el borrador o mueve el detalle a un reporte más largo antes de publicar.",
    );
  }
  if (privacyScore < 75) {
    suggestions.push(
      state.language === "en"
        ? "Activate privacy cleanup and manually review names, faces, locations, and sensitive data."
        : "Activa la limpieza de privacidad y revisa manualmente nombres, rostros, ubicaciones y datos sensibles.",
    );
  }
  if (mediaScore < 70) {
    suggestions.push(
      totalMedia
        ? state.language === "en"
          ? "Select the strongest media assets so the publication feels less text-heavy."
          : "Selecciona los activos multimedia más fuertes para que la publicación no dependa solo del texto."
        : state.language === "en"
          ? "Add media to the source experiences when the channel needs a more visual piece."
          : "Agrega multimedia a las experiencias fuente cuando el canal necesite una pieza más visual.",
    );
  }
  if (channelScore.score < 75 || readability.score < 75) {
    suggestions.push(
      state.language === "en"
        ? "Review tone, length, and call to action for the selected channel."
        : "Revisa el tono, la extensión y el llamado a la acción según el canal seleccionado.",
    );
  }
  if (!suggestions.length) {
    suggestions.push(
      state.language === "en"
        ? "Perform a final human review before exporting or sharing."
        : "Haz una revisión humana final antes de exportar o compartir.",
    );
  }
  return suggestions.slice(0, 3);
}

function renderPublicationMedia(media) {
  if (!media.length) return `<p class="card-meta">${escapeHtml(t("labels.publicationMediaEmpty"))}</p>`;
  const included = media.filter((item) => item.included !== false).length;
  return `
    <section class="publication-media">
      <div class="publication-section-heading">
        <div>
          <h3>${escapeHtml(t("labels.publicationMedia"))} · ${included}/${media.length}</h3>
          <p class="card-meta">${escapeHtml(t("labels.publicationMediaHelp"))}</p>
        </div>
      </div>
      <div class="publication-media-grid">
        ${media.map(renderPublicationMediaItem).join("")}
      </div>
    </section>
  `;
}

function renderPublicationMediaItem(item) {
  const checked = item.included !== false ? "checked" : "";
  const stateClass = item.included === false ? "publication-media-excluded" : "";
  const control = `
    <label class="publication-media-toggle">
      <input type="checkbox" data-publication-media-id="${escapeHtml(item.id)}" ${checked} />
      <span>${escapeHtml(item.included === false ? t("labels.publicationMediaExcluded") : t("labels.publicationMediaIncluded"))}</span>
    </label>
  `;
  const caption = renderPublicationMediaCaption(item);
  if (!item.url && !item.dataUrl) {
    return `<figure class="publication-file ${stateClass} media-sync-missing">${renderPublicationMediaSyncNotice(item)}${caption}${control}</figure>`;
  }
  const source = escapeHtml(item.url || item.dataUrl);
  if (item.type.startsWith("image/")) {
    return `<figure class="${stateClass}"><img src="${source}" alt="${escapeHtml(item.name)}" loading="lazy" />${caption}${control}</figure>`;
  }
  if (item.type.startsWith("video/")) {
    return `<figure class="${stateClass}"><video src="${source}" controls muted playsinline preload="metadata"></video>${caption}${control}</figure>`;
  }
  if (item.type.startsWith("audio/")) {
    return `<figure class="publication-audio ${stateClass}"><audio src="${source}" controls preload="metadata"></audio>${caption}${control}</figure>`;
  }
  return `<figure class="publication-file ${stateClass}">${caption}${control}</figure>`;
}

function renderPublicationMediaSyncNotice(item) {
  return `
    <div class="publication-media-sync">
      <strong>${escapeHtml(t("labels.attachmentNeedsSync"))}</strong>
      <small>${escapeHtml(t("labels.attachmentNeedsSyncDetail"))}</small>
    </div>
  `;
}

function renderPublicationMediaCaption(item) {
  const context = [item.analyticalText, item.manualNote].filter(Boolean).join(" ");
  const tags = (item.tags || []).slice(0, 4);
  return `
    <figcaption class="publication-media-caption">
      <strong title="${escapeHtml(item.name)}">${escapeHtml(item.name)}</strong>
      <span title="${escapeHtml(item.experienceTitle)}">${escapeHtml(item.experienceTitle)}</span>
      <span class="publication-provenance ${item.isDemo ? "is-demo" : "is-user"}">${escapeHtml(item.provenance || "")}</span>
      ${
        context || tags.length
          ? `<small><b>${escapeHtml(t("labels.publicationMediaContext"))}:</b> ${escapeHtml(context || tags.join(", "))}</small>`
          : ""
      }
    </figcaption>
  `;
}

function handlePublicationMediaSelection(event) {
  const input = event.target.closest("[data-publication-media-id]");
  if (!input) return;
  const draft = state.currentPublicationDraft || state.publicationDrafts[0];
  if (!draft) return;
  const mediaId = input.dataset.publicationMediaId;
  draft.media = (draft.media || []).map((item) => (item.id === mediaId ? { ...item, included: input.checked } : item));
  draft.approvalStatus = "review";
  draft.approvedAt = "";
  addPublicationHistory(draft, "media", input.checked ? t("labels.publicationMediaIncluded") : t("labels.publicationMediaExcluded"));
  state.currentPublicationDraft = draft;
  state.publicationDrafts = state.publicationDrafts.map((item) => (item.id === draft.id ? draft : item));
  savePublicationDrafts();
  renderPublications();
}

function handlePublicationDraftEdit(event) {
  const field = event.target.closest("[data-publication-field]");
  if (!field) return;
  const draft = state.currentPublicationDraft || state.publicationDrafts[0];
  if (!draft) return;
  const key = field.dataset.publicationField;
  if (!["title", "summary", "body"].includes(key)) return;
  draft[key] = field.value;
  draft.approvalStatus = "review";
  draft.approvedAt = "";
  addPublicationHistory(draft, "edited", t(`labels.publication${key.charAt(0).toUpperCase() + key.slice(1)}Field`) || key, { coalesceMs: 15000 });
  state.currentPublicationDraft = draft;
  state.publicationDrafts = state.publicationDrafts.map((item) => (item.id === draft.id ? draft : item));
  savePublicationDrafts();
  document.getElementById("publicationStatus").textContent = t("labels.publicationSaved");
  document.querySelectorAll(`[data-publication-final="${key}"]`).forEach((node) => {
    node.textContent = draft[key];
  });
  renderPublicationDraftListOnly();
}

function handlePublicationTemplateClick(event) {
  const button = event.target.closest("[data-publication-template]");
  if (!button) return;
  const draft = state.currentPublicationDraft || state.publicationDrafts[0];
  const template = publicationTemplates.find((item) => item.id === button.dataset.publicationTemplate);
  if (!draft || !template) return;
  draft.templateId = template.id;
  draft.type = template.type;
  draft.style = template.style;
  draft.channel = template.channel;
  draft.approvalStatus = "review";
  draft.approvedAt = "";
  addPublicationHistory(draft, "template", `${displayPublicationType(template.type)} · ${displayPublicationStyle(template.style)} · ${template.channel}`);
  state.currentPublicationDraft = draft;
  state.publicationDrafts = state.publicationDrafts.map((item) => (item.id === draft.id ? draft : item));
  document.getElementById("publicationTypeInput").value = template.type;
  document.getElementById("publicationStyleInput").value = template.style;
  document.getElementById("publicationChannelInput").value = template.channel;
  savePublicationDrafts();
  document.getElementById("publicationStatus").textContent = t("labels.publicationTemplateSelected");
  renderPublications();
}

function handlePublicationApprovalClick(event) {
  const button = event.target.closest("[data-publication-approval]");
  if (!button) return;
  const draft = state.currentPublicationDraft || state.publicationDrafts[0];
  if (!draft) return;
  const approved = button.dataset.publicationApproval === "approved";
  draft.approvalStatus = approved ? "approved" : "review";
  draft.approvedAt = approved ? new Date().toISOString() : "";
  addPublicationHistory(draft, "approval", displayPublicationApprovalStatus(draft.approvalStatus));
  state.currentPublicationDraft = draft;
  state.publicationDrafts = state.publicationDrafts.map((item) => (item.id === draft.id ? draft : item));
  savePublicationDrafts();
  document.getElementById("publicationStatus").textContent = approved
    ? t("labels.publicationApprovedMessage")
    : t("labels.publicationReviewMessage");
  renderPublications();
}

function renderPublicationDraftListOnly() {
  document.getElementById("publicationCount").textContent = `${state.publicationDrafts.length} ${t("labels.items")}`;
  document.getElementById("publicationDraftList").innerHTML = state.publicationDrafts.length
    ? state.publicationDrafts.map(renderPublicationDraftItem).join("")
    : `<p class="card-meta">${t("labels.publicationHistoryEmpty")}</p>`;
}

function renderPublicationDraftItem(draft) {
  return `
    <article class="publication-draft-item">
      <button class="ghost-button" type="button" data-publication-action="open" data-publication-id="${escapeHtml(draft.id)}">
        <strong>${escapeHtml(draft.title)}</strong>
        <span>${escapeHtml(formatDate(draft.createdAt))} · ${escapeHtml(displayPublicationType(draft.type))}</span>
      </button>
      <button class="danger-button" type="button" data-publication-action="delete" data-publication-id="${escapeHtml(draft.id)}">${t("buttons.delete")}</button>
    </article>
  `;
}

function handlePublicationDraftAction(event) {
  const button = event.target.closest("[data-publication-action]");
  if (!button) return;
  const draft = state.publicationDrafts.find((item) => item.id === button.dataset.publicationId);
  if (!draft) return;
  if (button.dataset.publicationAction === "open") {
    state.currentPublicationDraft = draft;
  } else if (button.dataset.publicationAction === "delete") {
    state.publicationDrafts = state.publicationDrafts.filter((item) => item.id !== draft.id);
    if (state.currentPublicationDraft?.id === draft.id) state.currentPublicationDraft = state.publicationDrafts[0] || null;
    savePublicationDrafts();
  }
  renderPublications();
}

