async function handleApiStatusClick(event) {
  const action = event.target.closest("[data-api-status-action]")?.dataset.apiStatusAction;
  if (action !== "refresh") return;
  const status = document.getElementById("embeddingStatus");
  if (status) {
    status.textContent = state.language === "en" ? "Checking local API..." : "Verificando API local...";
  }
  await hydrateFromApi();
  if (status) {
    status.textContent = state.apiOnline
      ? state.language === "en" ? "Local API available." : "API local disponible."
      : state.language === "en" ? "Local API unavailable; local mode active." : "API local no disponible; modo local activo.";
  }
  renderAdmin();
}

function buildUiQualityChecks() {
  const allManualSections = manualContent[state.language] || manualContent.es;
  const visibleManualSections = getFilteredManualSections();
  const manualFiltersActive = Boolean(
    state.manualFilters.query ||
      (state.manualFilters.section && state.manualFilters.section !== "all") ||
      (state.manualFilters.review && state.manualFilters.review !== "all"),
  );
  const mvpFlow = summarizeReadiness(buildMvpFlowChecks().map((check) => check.ok));
  const quickQa = summarizeReadiness(buildQuickQaChecks().map((check) => check.ok));
  const labels = state.language === "en"
    ? {
        open: "Open",
        clear: "Clear filters",
        version: "Current app version",
        versionDetail: `Loaded version ${APP_VERSION}.`,
        manual: "Manual content visible",
        manualDetail: manualFiltersActive
          ? `${visibleManualSections.length}/${allManualSections.length} visible sections with active filters.`
          : `${visibleManualSections.length}/${allManualSections.length} visible sections.`,
        manualBlocked: "Active filters are hiding the Manual.",
        api: "Local API/server status",
        apiDetail: state.apiStatus?.checkedAt ? `${state.apiStatus.message || ""} ${state.apiStatus.latencyMs ?? "-"} ms`.trim() : "No recent check.",
        mvp: "Complete MVP route",
        mvpDetail: `${mvpFlow.score}% · ${mvpFlow.ready}/${mvpFlow.total} stages ready.`,
        quick: "Quick verification available",
        quickDetail: `${quickQa.score}% · ${quickQa.ready}/${quickQa.total} checks ready.`,
        data: "Enough test data",
        dataDetail: `${state.experiences.length} experiences available.`,
        backup: "Backup evidence",
        backupDetail: state.backupAudit?.at ? `Backup recorded ${formatDate(state.backupAudit.at)}.` : "Run one backup before pilot testing.",
      }
    : {
        open: "Abrir",
        clear: "Limpiar filtros",
        version: "Versión actual de la app",
        versionDetail: `Versión cargada ${APP_VERSION}.`,
        manual: "Contenido del Manual visible",
        manualDetail: manualFiltersActive
          ? `${visibleManualSections.length}/${allManualSections.length} secciones visibles con filtros activos.`
          : `${visibleManualSections.length}/${allManualSections.length} secciones visibles.`,
        manualBlocked: "Los filtros activos están ocultando el Manual.",
        api: "Estado del servidor/API local",
        apiDetail: state.apiStatus?.checkedAt ? `${state.apiStatus.message || ""} ${state.apiStatus.latencyMs ?? "-"} ms`.trim() : "Sin verificación reciente.",
        mvp: "Ruta MVP completa",
        mvpDetail: `${mvpFlow.score}% · ${mvpFlow.ready}/${mvpFlow.total} etapas listas.`,
        quick: "Verificación rápida disponible",
        quickDetail: `${quickQa.score}% · ${quickQa.ready}/${quickQa.total} controles listos.`,
        data: "Datos suficientes para probar",
        dataDetail: `${state.experiences.length} experiencias disponibles.`,
        backup: "Evidencia de respaldo",
        backupDetail: state.backupAudit?.at ? `Respaldo registrado ${formatDate(state.backupAudit.at)}.` : "Ejecuta un respaldo antes de probar con pilotos.",
      };
  return [
    { key: "version", label: labels.version, ok: true, detail: labels.versionDetail, view: "admin", focus: "uiQualityPanel", action: labels.open },
    {
      key: "manual",
      label: labels.manual,
      ok: visibleManualSections.length > 0,
      detail: visibleManualSections.length > 0 ? labels.manualDetail : labels.manualBlocked,
      view: "manual",
      run: visibleManualSections.length > 0 ? "" : "clearManualFilters",
      action: visibleManualSections.length > 0 ? labels.open : labels.clear,
    },
    { key: "api", label: labels.api, ok: Boolean(state.apiOnline), detail: labels.apiDetail, view: "admin", focus: "apiStatusPanel", run: "refreshApiStatus", action: labels.open },
    { key: "mvp", label: labels.mvp, ok: mvpFlow.score >= 70, detail: labels.mvpDetail, view: "admin", focus: "mvpFlowPanel", action: labels.open },
    { key: "quick", label: labels.quick, ok: quickQa.total > 0, detail: labels.quickDetail, view: "admin", focus: "quickQaPanel", action: labels.open },
    { key: "data", label: labels.data, ok: state.experiences.length >= 3, detail: labels.dataDetail, view: "capture", action: labels.open },
    { key: "backup", label: labels.backup, ok: Boolean(state.backupAudit?.at), detail: labels.backupDetail, view: "admin", focus: "mvpClosurePanel", action: labels.open },
  ];
}

function buildUiQualityPayload() {
  const checks = buildUiQualityChecks();
  const readiness = summarizeReadiness(checks.map((check) => check.ok));
  const next = checks.find((check) => !check.ok);
  return {
    generatedAt: new Date().toISOString(),
    appVersion: APP_VERSION,
    language: state.language,
    score: readiness.score,
    ready: readiness.ready,
    total: readiness.total,
    api: {
      online: Boolean(state.apiOnline),
      checkedAt: state.apiStatus?.checkedAt || null,
      latencyMs: state.apiStatus?.latencyMs ?? null,
      mode: state.apiStatus?.mode || state.persistence || "local",
      service: state.apiStatus?.service || "",
    },
    nextAction: next
      ? {
          label: next.label,
          detail: next.detail,
          action: next.action,
          view: next.view || "",
          focus: next.focus || "",
          run: next.run || "",
        }
      : null,
    checks: checks.map((check) => ({
      key: check.key,
      label: check.label,
      ready: Boolean(check.ok),
      detail: check.detail,
      view: check.view || "",
      focus: check.focus || "",
      run: check.run || "",
    })),
  };
}

function buildUiQualityMarkdown(payload = buildUiQualityPayload()) {
  const labels = state.language === "en"
    ? { title: "Interface Quality Evidence", generated: "Generated", version: "Version", score: "Score", api: "Local API", next: "Next action", checks: "Controls", ready: "ready", review: "review" }
    : { title: "Evidencia de calidad de interfaz", generated: "Generado", version: "Versión", score: "Puntaje", api: "API local", next: "Siguiente acción", checks: "Controles", ready: "listo", review: "revisar" };
  return [
    `# ${labels.title}`,
    "",
    `**${labels.generated}:** ${formatDate(payload.generatedAt)}`,
    `**${labels.version}:** ${payload.appVersion}`,
    `**${labels.score}:** ${payload.score}% (${payload.ready}/${payload.total})`,
    "",
    `## ${labels.api}`,
    "",
    `- ${state.language === "en" ? "Online" : "En línea"}: ${payload.api.online ? "sí" : "no"}`,
    `- ${state.language === "en" ? "Mode" : "Modo"}: ${payload.api.mode}`,
    `- ${state.language === "en" ? "Latency" : "Latencia"}: ${payload.api.latencyMs == null ? "-" : `${payload.api.latencyMs} ms`}`,
    `- ${state.language === "en" ? "Checked" : "Verificada"}: ${payload.api.checkedAt ? formatDate(payload.api.checkedAt) : "-"}`,
    "",
    `## ${labels.next}`,
    "",
    payload.nextAction
      ? `${payload.nextAction.label}: ${payload.nextAction.detail} (${payload.nextAction.action})`
      : state.language === "en" ? "No visible interface blockers detected." : "No se detectan bloqueos visibles de interfaz.",
    "",
    `## ${labels.checks}`,
    "",
    ...payload.checks.map((check) => `- [${check.ready ? "x" : " "}] ${check.label}: ${check.detail} (${check.ready ? labels.ready : labels.review})`),
    "",
  ].join("\n");
}

function recordUiQualityAudit(action, payload = buildUiQualityPayload()) {
  const entry = {
    action,
    at: new Date().toISOString(),
    appVersion: APP_VERSION,
    score: payload.score,
    ready: payload.ready,
    total: payload.total,
    pending: payload.checks.filter((check) => !check.ready).map((check) => check.label).slice(0, 5),
  };
  const previousHistory = Array.isArray(state.uiQualityAudit?.history) ? state.uiQualityAudit.history : [];
  state.uiQualityAudit = {
    ...entry,
    history: [entry, ...previousHistory].slice(0, 5),
  };
  saveUiQualityAudit();
}

function describeUiQualityAudit() {
  if (!state.uiQualityAudit?.at) {
    return state.language === "en" ? "No interface quality evidence yet." : "Aún no hay evidencia de calidad de interfaz.";
  }
  const pending = state.uiQualityAudit.pending?.length
    ? state.uiQualityAudit.pending.join(" · ")
    : state.language === "en" ? "no pending controls" : "sin controles pendientes";
  return `${formatDate(state.uiQualityAudit.at)} · ${state.uiQualityAudit.score}% · ${pending}`;
}

async function copyUiQualityEvidence() {
  const payload = buildUiQualityPayload();
  const copied = await copyTextToClipboard(buildUiQualityMarkdown(payload));
  recordUiQualityAudit(copied ? "copy" : "copyBlocked", payload);
  renderAdmin();
}

function exportUiQualityEvidence(format) {
  const payload = buildUiQualityPayload();
  recordUiQualityAudit(format, payload);
  if (format === "json") {
    downloadBlob(new Blob([JSON.stringify(payload, null, 2)], { type: "application/json;charset=utf-8" }), "calidad-interfaz-mvp.json");
  } else {
    downloadBlob(new Blob([buildUiQualityMarkdown(payload)], { type: "text/markdown;charset=utf-8" }), "calidad-interfaz-mvp.md");
  }
  renderAdmin();
}

