function handlePilotParticipantSubmit(event) {
  event.preventDefault();
  const form = event.target.closest("form");
  if (!form) return;
  const data = new FormData(form);
  state.pilotParticipants.unshift({
    id: createId(),
    createdAt: new Date().toISOString(),
    name: String(data.get("name") || "").trim(),
    email: String(data.get("email") || "").trim(),
    role: String(data.get("role") || "").trim(),
    status: String(data.get("status") || "").trim(),
    accessOk: false,
    manualOk: false,
    testOk: false,
  });
  savePilotParticipants();
  renderAdmin();
}

function handlePilotParticipantClick(event) {
  const exportButton = event.target.closest("[data-pilot-participants-export]");
  if (exportButton) {
    exportPilotParticipantsCsv();
    return;
  }
  const checkInput = event.target.closest("[data-pilot-participant-check]");
  if (checkInput) {
    const item = state.pilotParticipants.find((entry) => entry.id === checkInput.dataset.pilotParticipantCheck);
    const field = checkInput.dataset.field;
    if (item && ["accessOk", "manualOk", "testOk"].includes(field)) {
      item[field] = Boolean(checkInput.checked);
      savePilotParticipants();
      renderAdmin();
    }
    return;
  }
  const completeButton = event.target.closest("[data-pilot-participant-complete]");
  if (completeButton) {
    const item = state.pilotParticipants.find((entry) => entry.id === completeButton.dataset.pilotParticipantComplete);
    if (item) {
      item.status = state.language === "en" ? "completed" : "completado";
      item.completedAt = new Date().toISOString();
      savePilotParticipants();
      renderAdmin();
    }
  }
}

