function calculatePilotFeedbackSummary() {
  const normalizedResolved = new Set(["resolved", "resuelto"]);
  const blockingSeverities = new Set(["high", "blocker", "alta", "bloqueante"]);
  const openItems = state.pilotFeedback.filter((item) => !normalizedResolved.has(String(item.status || "").toLowerCase()));
  const blockingOpen = openItems.filter((item) => blockingSeverities.has(String(item.severity || "").toLowerCase())).length;
  return {
    total: state.pilotFeedback.length,
    open: openItems.length,
    blockingOpen,
    resolved: state.pilotFeedback.length - openItems.length,
  };
}

