      multimodalTitle: "Multimodal foundation",
      multimodalDetail:
        assetAnalysisReadiness.total
          ? `${assetAnalysisReadiness.score}% multimodal analytical readiness: ${assetAnalysisReadiness.withText}/${assetAnalysisReadiness.total} assets with text, ${assetAnalysisReadiness.processingPending} pending processing, and ${assetAnalysisReadiness.suggested} locally suggested.`
          : "First increment active: filterable asset inventory with type, language, source, initial tags, manual metadata, analytical text, reuse readiness, and linked experience.",
      multimodalAction: "View capabilities",
      agendaTitle: "Intelligent Agenda",
      agendaDetail: "First MVP active: visual day/week calendar, local events, states, conflicts, blocked days, .ics import/export, and event-to-experience conversion.",
      agendaAction: "Open Agenda",
      publicationTitle: "Intelligent Publications",
